sys_script_include.script:
var GetKycDetails = Class.create();
GetKycDetails.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getKYCDetails: function() {
        var consumerSysId = this.getParameter('sysparm_consumer_sysid');
        if (!consumerSysId) {
            gs.error("No consumer sys_id provided");
            return "";
        } 
        var consumerGR = new GlideRecord("csm_consumer");
        if (!consumerGR.get(consumerSysId)) {
            gs.error("Consumer not found for sys_id: " + consumerSysId);
            return "";
        }
        var consumerUserGR = new GlideRecord("csm_consumer_user");
        consumerUserGR.addQuery("name", consumerGR.name);
        consumerUserGR.query();
        if (!consumerUserGR.next()) {
            gs.info("No consumer_user found for consumer: " + consumerGR.name);
            return "";
        }
        var profileGR = new GlideRecord("x_1811084_diya_c_0_customer_profile");
        profileGR.addQuery("user_id", consumerUserGR.user_name); 
        profileGR.query();

        if (profileGR.next()) {
			gs.info(profileGR.name+"p"+profileGR.aadhar_number);
             var kycData = {
            name: profileGR.name+ "", 
            aadhar_no: profileGR.aadhar_number + "",
            pan_no: profileGR.pan_number + "",
            driving_license_no: profileGR.driving_license_number + "",
            dl_issued_d: profileGR.dl_issued_date + "",
            dl_expiry_d: profileGR.dl_expiry_date + ""
        };
        }
		else
		{
			return "";
		}
        return JSON.stringify(kycData);
    }
});
